const a = Math.abs(P.a) < 0.1 ? 0.1 : P.a, r1 = P.r1, r2 = P.r2;
// factored form a(x - r1)(x - r2): same parabola read three ways
const f = (x) => a * (x - r1) * (x - r2);
v.fn(f, { color: H.colors.accent, width: 3 });
// derived vertex (axis of symmetry midway between the roots)
const h = (r1 + r2) / 2;
const k = f(h);
v.line(h, -6, h, 12, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
v.dot(h, k, { r: 7, fill: H.colors.warn });
// roots (factored form reads them straight off)
v.dot(r1, 0, { r: 6, fill: H.colors.good });
v.dot(r2, 0, { r: 6, fill: H.colors.good });
// standard-form y-intercept c = a*r1*r2 (factored form reads it at x=0)
const c = f(0);
v.dot(0, c, { r: 6, fill: H.colors.accent2 });
